function isLocalOffer(o){return o[7]===undefined}
function offerLoad(i){return i%2?{pallets:26,tonnes:22,goods:'Produits secs',truck:'Semi-remorque tautliner'}:{pallets:18,tonnes:12,goods:'Marchandises sous température contrôlée',truck:'Semi-remorque frigorifique'}}
function truckCatalog(){return [{type:'Semi-remorque bâchée',payload:24,pallets:33,volume:90,cold:false},{type:'Semi-remorque tautliner',payload:24,pallets:33,volume:90,cold:false},{type:'Semi-remorque frigorifique',payload:20,pallets:33,volume:82,cold:true},{type:'Porteur frigorifique',payload:12,pallets:15,volume:45,cold:true},{type:'Porteur bâché',payload:12,pallets:15,volume:45,cold:false},{type:'Fourgon',payload:3.5,pallets:8,volume:20,cold:false}]}
function bidsForOffer(o){let target=Number(o[4].replace(/[^0-9]/g,'')),i=Math.max(0,offers.indexOf(o)),load=offerLoad(i),local=isLocalOffer(o),margin=local?Math.min(800,Math.round(target*.12)):o[7],needCold=/frais|frigor|pharma|température/i.test(load.goods+' '+o[3]),suitable=truckCatalog().filter(v=>v.payload>=load.tonnes&&v.pallets>=load.pallets&&(!needCold||v.cold));if(!suitable.length)suitable=truckCatalog().filter(v=>v.payload>=load.tonnes&&v.pallets>=load.pallets);let order=[1,0,3,2,4];return order.map((n,j)=>{let c=carriers[n%carriers.length],v=suitable[j%suitable.length]||truckCatalog()[0],m=margin;return {carrier:c[0],price:target-m,ontime:c[2],fleet:c[1],insurance:c[3],eta:['18 h 30','20 h','22 h','24 h','26 h'][j],note:'Rapprochement automatique : charge utile, palettes et marchandise',vehicle:`${v.type} · ${v.payload} t · ${v.pallets} palettes · ${v.volume} m³${v.cold?' · froid':''}`,margin:m,payload:v.payload,compatible:v.payload>=load.tonnes&&v.pallets>=load.pallets}})}
const demoMapInteractions=(()=>{document.querySelector('#app').addEventListener('change',e=>{if(e.target.id==='dashboardStart'||e.target.id==='dashboardEnd'){let a=e.target.id==='dashboardStart'?e.target.value:dashboardStart,b=e.target.id==='dashboardEnd'?e.target.value:dashboardEnd;if(a&&b&&a>b){toast('La date de début doit précéder la date de fin');return}dashboardStart=a||dashboardStart;dashboardEnd=b||dashboardEnd;render()}});document.addEventListener('click',e=>{let button=e.target.closest('[data-offer-open]');if(!button)return;e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();let i=Number(button.dataset.offerOpen),o=offers[i];if(!o)return;selectedOfferCode=o[0];selectedBidIndex=0;let l=offerLoad(i),b=bidsForOffer(o);modal(`Appel d’offres · ${o[0]}`,`<span class="badge">${esc(o[6])}</span><h2>${esc(o[2])}</h2><p>${esc(o[1])} · ${esc(l.goods)}</p><div class="detail-row"><span>Charge déclarée</span><b>${l.pallets} palettes · ${l.tonnes} t</b></div><div class="detail-row"><span>Camion(s) suggéré(s)</span><b>${Math.max(1,Math.ceil(l.pallets/33),Math.ceil(l.tonnes/24))} · ${esc(l.truck)}</b></div><div class="detail-row"><span>Prix chargeur</span><b>${esc(o[4])} HT</b></div><div class="detail-row"><span>Rapprochement</span><b>${b.filter(x=>x.compatible).length} transporteurs compatibles</b></div><div class="detail-row"><span>Règle de marge</span><b>${isLocalOffer(o)?'Maximum 800 DH':`Cible : ${o[7].toLocaleString('fr-FR')} DH`}</b></div><div class="detail-row"><span>Départ et clôture</span><b>${esc(o[5])} · sablier ${i%2?'24 h':'12 h'}</b></div><p class="capacity-disclaimer">Suggestion automatique selon palettes, poids et équipement. Vérifier la capacité réelle du véhicule avant confirmation.</p>`,'Attribuer la mission');return},true)})();

function carrierDirectory(){return [['Trans Atlas','32 véhicules · 8 semi / 4 frigo','98 %','Valide','Solvable · règlement moyen 2 j','Retard moyen 1,4 j','RC transport · valable au 30 juin 2027'],['Nord Cargo','24 véhicules · 6 semi / 3 frigo','96 %','Valide','Solvable · règlement moyen 4 j','Retard moyen 2,1 j','RC transport · valable au 15 mai 2027'],['Souss Transport','18 véhicules · 3 semi / 5 frigo','94 %','À renouveler','À surveiller · 18 j de retard','Retard moyen 3,6 j','Assurance à renouveler sous 30 jours'],['Maghreb Express','22 véhicules · 5 semi / 2 porteurs','97 %','Valide','Solvable · règlement moyen 3 j','Retard moyen 1,8 j','RC transport · valable au 12 août 2027'],['Rif Logistique','16 véhicules · 4 semi / 2 porteurs','95 %','Valide','Solvable · règlement moyen 5 j','Retard moyen 2,8 j','RC transport · valable au 20 sept. 2027']]}
document.addEventListener('click',e=>{let row=e.target.closest('[data-row="carriers"],[data-row="shippers"]');if(!row)return;e.preventDefault();e.stopImmediatePropagation();selected=Number(row.dataset.index)||0;render()},true);
